def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r-1][c]==2 and grid[r+1][c]==2 and grid[r][c-1]==2 and grid[r][c+1]==2:
                centers.append((r,c))
    for i,(r,c) in enumerate(centers):
        for rr,cc in centers[i+1:]:
            if r==rr and abs(c-cc)>2:
                lo,hi=sorted((c,cc))
                for x in range(lo+2,hi-1):
                    if grid[r][x]==0: out[r][x]=1
            elif c==cc and abs(r-rr)>2:
                lo,hi=sorted((r,rr))
                for y in range(lo+2,hi-1):
                    if grid[y][c]==0: out[y][c]=1
    return out
